questionvariables.text:
dp(num, dp) := block(if num*10^dp-floor(num*10^dp)<0.5 then return(float(floor(num*10^dp)/(10^dp))) else return(float(ceiling(num*10^dp)/(10^dp))));

/* Randomising measurements */

lenAB:rand_with_prohib(1,49,[10,20,30,40])/10+10;
lenAC:rand_with_prohib(1,49,[10,20,30,40])/10+5;
angCAB:rand_with_prohib(1,14,[5,10])*2+50;

/* Solutions */

tans1:sqrt(lenAB^2 + lenAC^2 - 2*lenAB*lenAC*cos(angCAB*%pi/180));

angBCA:arctan(lenAB*sin(angCAB*%pi/180)/(lenAC-lenAB*cos(angCAB*%pi/180)))*180/%pi;

tans2: if angBCA<0 then angBCA+180 else angBCA;

feedbackvariables.text:
/* Node 1: Correct answer (2) */
/* Node 2: Worked solution */
/* Node 3: Correct answer, incorrectly rounded (1) */
node3_test: if abs(ans1-tans1)<=0.01 then 1 else 0;

/* Node 4: Finds square of BC (1) */
node4_error: lenAB^2 + lenAC^2 - 2*lenAB*lenAC*cos(angCAB*%pi/180);

/* Node 5: Uses sine instead of cosine (1) */
node5_error: sqrt(lenAB^2 + lenAC^2 - 2*lenAB*lenAC*sin(angCAB*%pi/180));

/* Node 6: N4-5 errors with incorrect rounding (feedback) */
node6_test: if abs(ans1-node4_error)<=0.01 or abs(ans1-node5_error)<=0.01 then 1 else 0;

/* Node 1: Correct answer */
/* Node 2: Worked solution */
/* Node 3: ECF (3) */
ecf_angBCA:arcsin(sin(angCAB*%pi/180)*lenAB/ans1)*180/%pi;
ecf2: if angBCA<0 then 180-ecf_angBCA else angBCA;

/* Node 4: Correct answer, incorrect rounding (2) */
node4_test: if abs(ans2-tans2)<=0.1 then 1 else 0;

/* Node 5: ECF, incorrect rounding (2) */
node5_test: if abs(ans2-ecf2)<=0.1 then 1 else 0;

/* Node 6: Gives acute/obtuse angle incorrectly (1) */
node6_test: if abs(ans2-(180-tans2))<=0.1 then 1 else 0;

/* Node 7: ECF, gives acute/obtuse angle incorrectly (1) */
node7_test: if abs(ans2-(180-ecf2))<=0.1 then 1 else 0;

/* Node 8: Uses sine rule incorrectly (a*sin(A)=b*sin(B) or a/sin(A) = sin(B)/b) (feedback) */
node8_errorA: arcsin(sin(angCAB*%pi/180)*ans1/lenAB)*180/%pi;
node8_errorB: arcsin(ans1*lenAB/sin(angCAB*%pi/180))*180/%pi;
node8_test: if abs(ans2-node8_errorA)<=0.1 or abs(ans2-(180-node8_errorA))<=0.1 or abs(ans2-node8_errorB)<=0.1 or abs(ans2-(180-node8_errorB))<=0.1 then 1 else 0;

/* Node 9: Uses cosine in place of sine (feedback) */
node9_error: arccos(cos(angCAB*%pi/180)*lenAB/ans1)*180/%pi;
node9_test: if abs(ans2-node9_error)<=0.1 or abs(ans2-(180-node9_error))<=0.1 then 1 else 0;
